const listAllPendingTasks = `-- name: ListAllPendingTasks :many
SELECT id, attributes, spec, status, unique_tag, started_at, created_at, updated_at, attempts, locked_at, worker_id, serial_key, serial_id, priority, weight, parent_task_id, lease_version, lease_expires_at, lease_duration_ms, concurrency_wait_tag, concurrency_retry_at, lease_tags FROM anclax.tasks
WHERE
    status = 'pending'
    AND (
        started_at IS NULL OR started_at < NOW()
    )
`

func (q *Queries) ListAllPendingTasks(ctx context.Context) ([]*AnclaxTask, error) {
	rows, err := q.db.Query(ctx, listAllPendingTasks)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []*AnclaxTask
	for rows.Next() {
		var i AnclaxTask
		if err := rows.Scan(
			&i.ID,
			&i.Attributes,
			&i.Spec,
			&i.Status,
			&i.UniqueTag,
			&i.StartedAt,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.Attempts,
			&i.LockedAt,
			&i.WorkerID,
			&i.SerialKey,
			&i.SerialID,
			&i.Priority,
			&i.Weight,
			&i.ParentTaskID,
			&i.LeaseVersion,
			&i.LeaseExpiresAt,
			&i.LeaseDurationMs,
			&i.ConcurrencyWaitTag,
			&i.ConcurrencyRetryAt,
			&i.LeaseTags,
		); err != nil {
			return nil, err
		}
		items = append(items, &i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

